456	func EnsureMetadataBranch(ctx context.Context, repo *git.Repository) error {
457		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
458	
459		// Check if remote-tracking branch exists (e.g., after clone/fetch)
460		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
461		remoteRef, remoteErr := repo.Reference(remoteRefName, true)
462		if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
463			return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
464		}
465	
466		// Check if local branch already exists
