		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  emptyTreeHash,
		Author:    sig,
		Committer: sig,
		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
	}
	// Note: No ParentHashes - this is an orphan commit

	// Sign the orphan commit when signing is enabled, matching the path used
	// for every other metadata-branch commit (see metadata_reconcile.go and
	// push_common.go). Without this, repos that enforce a "verified
	// signatures" ruleset on entire/* refs reject the very first push of
	// the metadata branch with GH013, even though every later commit on it
	// is correctly signed.
	checkpoint.SignCommitBestEffort(ctx, commit)

	commitObj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(commitObj); err != nil {
		return fmt.Errorf("failed to encode orphan commit: %w", err)
	}
	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
	if err != nil {
		return fmt.Errorf("failed to store orphan commit: %w", err)
	}

	// Create branch reference
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to create metadata branch: %w", err)
	}
	MirrorCommittedMetadataRefBestEffort(ctx, repo)

	fmt.Fprintf(os.Stderr, "  ✓ Created orphan branch %s for session metadata\n", paths.MetadataBranchName)
	return nil
}

// metadataBranchHasCheckpoints reports whether the branch tip tree contains at
// least one checkpoint shard (<id[:2]>/<id[2:]>/). Root-level config files such
// as vercel.json — written into the tree by orphan initialization in
// vercel-enabled repos — are not checkpoints, so a freshly-initialized orphan
// (empty tree, or vercel.json-only) reports false.
//
// This is the "is this branch un-initialized / safe to adopt from the
// authoritative remote" predicate. A literal empty-tree check missed
// vercel-enabled orphans, leaving them unhealed (issue #1374). Only the tip
// commit is inspected; the walk short-circuits on the first shard found.
func metadataBranchHasCheckpoints(ctx context.Context, repo *git.Repository, ref *plumbing.Reference) (bool, error) {
	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return false, fmt.Errorf("failed to get commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return false, fmt.Errorf("failed to get tree: %w", err)
	}
	found := false
	walkErr := checkpoint.WalkCheckpointShards(ctx, repo, tree, func(id.CheckpointID, plumbing.Hash) error {
		found = true
		return errStop
	})
	if walkErr != nil && !errors.Is(walkErr, errStop) {
		return false, fmt.Errorf("failed to scan checkpoint shards: %w", walkErr)
	}
	return found, nil
}

